update public.academy_modules set learning_objectives = array['Maintain accurate candidate information and records.', 'Handle resumes and recruitment documents professionally.', 'Record candidate qualifications, skills and experience accurately.', 'Track candidate source and recruiter ownership.', 'Maintain factual recruiter notes and follow-up history.', 'Identify and handle possible duplicate candidate records.', 'Understand and correctly use recruitment pipeline stages.', 'Track candidate progress and pending recruitment actions.', 'Manage candidate follow-ups and status updates accurately.', 'Coordinate recruitment activities from interview through joining.', 'Maintain accurate recruitment documentation and daily reports.', 'Manage recruiter priorities, pending actions and daily recruitment operations.']::text[] where module_number = 5;
insert into public.lessons (module_id, sort_order, title, description, content_type, estimated_minutes, is_required, status, content)
select id, 1, 'Candidate Profile and Basic Information', 'What a complete, accurate candidate record contains and why it matters.', 'text', 15, true, 'active', '{"section": "A. Candidate Management", "blocks": [{"type": "h", "text": "Why the candidate record matters"}, {"type": "p", "text": "Every decision in recruitment — screening, submission, interview, offer, joining — depends on the candidate record. An incomplete or wrong record causes missed calls, wrong submissions and lost candidates."}, {"type": "h", "text": "Basic information fields"}, {"type": "terms", "items": [{"term": "Candidate ID", "definition": "Unique identifier assigned when the record is created. Never reused, never changed."}, {"term": "Employee ID (where applicable)", "definition": "Assigned only after the candidate joins as an employee. Do not confuse it with the Candidate ID."}, {"term": "Name", "definition": "Full name as on the resume or ID proof. Check spelling with the candidate."}, {"term": "Email", "definition": "Primary contact email, verified by sending a confirmation."}, {"term": "Phone", "definition": "Primary mobile number with country code; note an alternate if provided."}, {"term": "Location", "definition": "Current city and area, plus willingness to relocate if relevant."}, {"term": "Joining date", "definition": "Recorded only when confirmed by the candidate and the client."}, {"term": "Designation", "definition": "Current or most recent job title."}, {"term": "Department", "definition": "Function the candidate works in, e.g. Procurement, Customer Support."}, {"term": "Candidate source", "definition": "Where the candidate came from, e.g. Employee Referral, Job Portal."}, {"term": "Ownership", "definition": "The recruiter responsible for the candidate''s next action."}]}, {"type": "h", "text": "Information, notes and status are different"}, {"type": "terms", "items": [{"term": "Candidate information", "definition": "Facts about the candidate: contact details, experience, skills, location. Changes rarely."}, {"term": "Recruiter notes", "definition": "Dated, factual record of conversations and observations, e.g. ''12 Mar, 4:10 pm — confirmed 30-day notice.''"}, {"term": "Recruitment status", "definition": "The candidate''s current stage, e.g. Screened or Interview Scheduled. Changes as the process moves."}]}, {"type": "example", "title": "Fictional record", "text": "Candidate ID C-10482 · Ms. Nandini S. · nandini.s@example.com · +91 98XXXXXX21 · Pune (Hinjewadi) · Purchase Executive, Procurement · Source: Employee Referral · Owner: Recruiter Arjun M. · Status: Screened."}, {"type": "h", "text": "Updating information correctly"}, {"type": "list", "items": ["Update only after confirming with the candidate or a document.", "Change one field at a time and record why in a note.", "Never overwrite a phone or email without confirming the new one works.", "Keep records complete — a missing field becomes a missed action later."]}, {"type": "callout", "text": "If information is not confirmed, leave it blank and add a follow-up action. A blank field is better than a guessed one."}]}'::jsonb from public.academy_modules where module_number = 5
