select id, 2, 'Resume and Document Handling', 'Collect, organise and protect candidate documents professionally.', 'text', 15, true, 'active', '{"section": "A. Candidate Management", "blocks": [{"type": "h", "text": "Collecting resumes and documents"}, {"type": "p", "text": "Ask for the latest resume in a standard format. At later stages, collect only the documents the process needs (e.g. relieving letter, ID proof at joining)."}, {"type": "steps", "items": [{"title": "Collect", "text": "Request the current resume; confirm it is the latest version."}, {"title": "Check completeness", "text": "Contact details, experience dates, education, current role all present."}, {"title": "Associate correctly", "text": "Attach the document to the correct Candidate ID — check name and phone before saving."}, {"title": "Name clearly", "text": "Use a consistent format."}, {"title": "Keep current", "text": "Replace outdated versions; keep a note of when the update was received."}]}, {"type": "compare", "title": "Document naming", "good": "C-10482_Nandini_S_Resume_2026-03.pdf", "bad": "resume final new (2).pdf", "goodLabel": "Clear", "badLabel": "Unclear"}, {"type": "h", "text": "Avoid duplicates and information loss"}, {"type": "list", "items": ["Do not attach the same resume twice to one record.", "Do not attach a resume to a different candidate with a similar name.", "Before replacing a document, confirm the new one is complete.", "Never delete a document without recording the reason."]}, {"type": "h", "text": "Protecting candidate information"}, {"type": "list", "items": ["Share resumes only with authorised people for the specific requirement.", "Do not forward candidate documents to personal email or chat groups.", "Do not download documents to shared or public computers.", "Mask ID numbers when they are not needed."]}, {"type": "callout", "text": "Candidate documents contain personal data. Handling them carelessly damages trust and may break company policy."}]}'::jsonb from public.academy_modules where module_number = 5
