select id, 3, 'Candidate Skills, Qualification and Experience', 'Scenario: compare candidate details against a requirement and spot gaps.', 'scenario', 18, true, 'active', '{"section": "A. Candidate Management", "blocks": [{"type": "h", "text": "What to capture"}, {"type": "terms", "items": [{"term": "Qualification", "definition": "Highest relevant education, institution and year."}, {"term": "Skills", "definition": "Tools and abilities with evidence of use, e.g. ''SAP MM — daily PO creation''."}, {"term": "Total experience", "definition": "All work experience, in years and months."}, {"term": "Relevant / role-specific experience", "definition": "Experience doing the work the requirement asks for."}, {"term": "Location", "definition": "Current location and commute or relocation fit."}, {"term": "Notice period", "definition": "Official notice, any buyout or early-release possibility."}, {"term": "Candidate expectations", "definition": "Expected CTC, work mode, shift preferences."}]}, {"type": "p", "text": "Compare each requirement point with the candidate''s information and classify it as Matched, Missing or Requires clarification."}, {"type": "h", "text": "Fictional scenario"}, {"type": "example", "title": "Requirement", "text": "Accounts Payable Executive, fictional client ''Meridian Logistics'', Hyderabad (Gachibowli), WFO. B.Com mandatory, 2–4 yrs AP experience, Tally or SAP FICO, notice ≤ 30 days, CTC up to 4.8 LPA."}, {"type": "example", "title": "Candidate (fictional)", "text": "Mr. Rahul K., B.Com 2020, 4 yrs 2 months total experience — 1 yr sales coordination, then 3 yrs 2 months AP at a fictional distribution firm. Uses Tally daily. Lives in Kukatpally. Notice: ''around a month''. CTC expectation not shared."}, {"type": "p", "text": "Identify matched information, missing information and information requiring clarification before reading the model answer."}, {"type": "answer", "title": "Model Analysis", "items": [{"term": "Matched", "definition": "B.Com; 3 yrs 2 months relevant AP experience (within 2–4); Tally; Hyderabad location."}, {"term": "Missing", "definition": "Expected CTC; current CTC; whether he has worked with vendor reconciliation."}, {"term": "Requires clarification", "definition": "Notice period (''around a month'' — confirm exact days and buyout); commute from Kukatpally to Gachibowli for WFO."}, {"term": "Note on experience", "definition": "Total 4.2 yrs but relevant is 3.2 yrs — record both separately."}]}]}'::jsonb from public.academy_modules where module_number = 5
