select id, 4, 'Candidate Source, Ownership and Recruiter Notes', 'Practice: record source, ownership and factual notes correctly.', 'practice', 18, true, 'active', '{"section": "A. Candidate Management", "blocks": [{"type": "h", "text": "Candidate sources"}, {"type": "terms", "items": [{"term": "Job Portal", "definition": "Candidate found or applied via a job board."}, {"term": "Professional Network", "definition": "Found through a professional networking platform."}, {"term": "Employee Referral", "definition": "Referred by a current employee — record the referrer."}, {"term": "Consultant", "definition": "Submitted by a partner recruitment consultant."}, {"term": "Campus", "definition": "Sourced through a college placement drive."}, {"term": "Job Fair", "definition": "Met at a recruitment fair or event."}, {"term": "Walk-in", "definition": "Attended a walk-in drive in person."}, {"term": "Direct Application", "definition": "Applied directly through the company''s careers channel."}, {"term": "Internal Source", "definition": "Existing database or an internal employee moving roles."}]}, {"type": "p", "text": "Source tracking shows which channels bring suitable candidates and prevents disputes about who introduced a candidate."}, {"type": "h", "text": "Ownership"}, {"type": "p", "text": "The owner is the recruiter accountable for the candidate''s next action. Ownership changes only with a recorded handover."}, {"type": "h", "text": "Recruiter notes and follow-up history"}, {"type": "list", "items": ["Write facts: what was said, agreed and pending.", "Include date and time of every note.", "End each note with a next action and due date.", "Keep follow-up history complete — every call attempt counts."]}, {"type": "compare", "title": "Writing a note", "good": "14 Mar, 11:20 am — Spoke to candidate. Interested. Notice 30 days, early release possible. Expected CTC 5 LPA. Next: share JD by email today; follow up 15 Mar 5 pm.", "bad": "Candidate seemed arrogant, probably won''t join. Call later.", "goodLabel": "Factual", "badLabel": "Subjective"}, {"type": "callout", "text": "Never record opinions about appearance, age, gender, religion, caste, accent or personal life. Notes may be read by clients, managers and auditors."}, {"type": "h", "text": "Practice exercise"}, {"type": "example", "title": "Fictional situation", "text": "On 18 Mar at 3:45 pm, Recruiter Priya D. calls Ms. Farah A., who was referred by employee Sanjay P. Farah is interested in the Inside Sales role, currently in Noida, notice 60 days (negotiable to 45), expects 4.5 LPA, and asks for the JD on email. She can talk again on 20 Mar after 6 pm."}, {"type": "p", "text": "Write the source, owner, note and next action for this candidate."}, {"type": "answer", "title": "Model Record", "items": [{"term": "Source", "definition": "Employee Referral — referrer: Sanjay P."}, {"term": "Owner", "definition": "Priya D."}, {"term": "Note", "definition": "18 Mar, 3:45 pm — Spoke to candidate. Interested in Inside Sales. Location Noida. Notice 60 days, negotiable to 45. Expected CTC 4.5 LPA. Requested JD by email."}, {"term": "Next action", "definition": "Send JD by email on 18 Mar."}, {"term": "Next follow-up", "definition": "20 Mar after 6 pm — confirm interest after JD review and notice negotiation."}]}]}'::jsonb from public.academy_modules where module_number = 5
