select id, 5, 'Duplicate Handling and Accurate Candidate Records', 'Scenario: identify possible duplicates without losing or overwriting information.', 'scenario', 17, true, 'active', '{"section": "A. Candidate Management", "blocks": [{"type": "h", "text": "Why duplicates are a problem"}, {"type": "p", "text": "Duplicate records split history across two places, cause two recruiters to call the same candidate, and can lead to the same candidate being submitted twice to a client."}, {"type": "h", "text": "How to check"}, {"type": "steps", "items": [{"title": "Candidate ID", "text": "Search the ID first if the candidate already has one."}, {"title": "Email", "text": "Exact email match is a strong indicator."}, {"title": "Phone", "text": "Exact phone match is a strong indicator; numbers can change, so confirm."}, {"title": "Name", "text": "Similar names alone are weak — many people share names."}, {"title": "Resume information", "text": "Compare employers, dates and education."}]}, {"type": "h", "text": "Rules"}, {"type": "list", "items": ["Never merge or overwrite on a name match alone.", "Confirm identity with the candidate before combining information.", "Keep the older record''s history; add new information, do not replace it.", "If unclear, escalate to your team lead with both Candidate IDs."]}, {"type": "h", "text": "Fictional scenario"}, {"type": "example", "title": "Existing record", "text": "C-09811 · Mohammed Imran · imran.m@example.com · +91 97XXXXXX40 · Chennai · Last updated 8 months ago · Status: Not Interested."}, {"type": "example", "title": "New profile received", "text": "Md. Imran · imran.work@example.com · +91 97XXXXXX40 · Bengaluru · Resume shows the same previous employer and degree year as C-09811."}, {"type": "answer", "title": "Model Approach", "items": [{"term": "Assessment", "definition": "Possible duplicate — same phone, same employer history and degree year; different email and city."}, {"term": "Action", "definition": "Call the candidate on the shared number and confirm identity, new email and relocation to Bengaluru."}, {"term": "Record update", "definition": "If confirmed, update C-09811: add new email and location with a dated note. Do not create a new record."}, {"term": "Status", "definition": "Move from Not Interested to the correct current stage only after the candidate confirms interest."}, {"term": "If unconfirmed", "definition": "Do not merge; escalate to the team lead with both details."}]}]}'::jsonb from public.academy_modules where module_number = 5
