select id, 6, 'Recruitment Pipeline Stages', 'The standard stages and statuses a candidate moves through.', 'text', 18, true, 'active', '{"section": "B. Recruitment Pipeline", "blocks": [{"type": "h", "text": "The pipeline"}, {"type": "p", "text": "Sourced → Contacted → Interested → Screened → Shortlisted → Interview Scheduled → Interview Attended → Selected → Offered → Offer Accepted → Joined"}, {"type": "steps", "items": [{"title": "Sourced", "text": "Profile identified as potentially relevant; no contact yet."}, {"title": "Contacted", "text": "Recruiter has reached out by call or message."}, {"title": "Interested", "text": "Candidate has confirmed interest in the role."}, {"title": "Screened", "text": "Screening call completed and evaluated against the requirement."}, {"title": "Shortlisted", "text": "Profile approved for submission or interview."}, {"title": "Interview Scheduled", "text": "Date, time and mode confirmed with candidate and interviewer."}, {"title": "Interview Attended", "text": "Candidate attended — confirmed by interviewer or client."}, {"title": "Selected", "text": "Authorised confirmation of selection received."}, {"title": "Offered", "text": "Offer formally released to the candidate."}, {"title": "Offer Accepted", "text": "Candidate has accepted the offer in writing."}, {"title": "Joined", "text": "Candidate has actually reported and joined on the joining date."}]}, {"type": "h", "text": "Additional statuses"}, {"type": "terms", "items": [{"term": "Rejected", "definition": "Not selected at screening or interview; record the stage and reason."}, {"term": "Not Interested", "definition": "Candidate declined the opportunity; record the reason if shared."}, {"term": "No Response", "definition": "Candidate did not respond after the agreed number of attempts."}, {"term": "On Hold", "definition": "Process paused — by client or candidate — with a review date."}, {"term": "Dropout", "definition": "Candidate withdrew after offer or before joining."}, {"term": "Absconded", "definition": "Candidate joined but stopped reporting without notice."}]}, {"type": "callout", "text": "Always keep the candidate at the correct current stage. The pipeline is only useful if it reflects what has actually happened."}]}'::jsonb from public.academy_modules where module_number = 5
