select id, 7, 'Tracking Candidate Progress and Pending Actions', 'Practice: build a tracking record so no candidate is forgotten.', 'practice', 20, true, 'active', '{"section": "B. Recruitment Pipeline", "blocks": [{"type": "h", "text": "What to track"}, {"type": "terms", "items": [{"term": "Current status", "definition": "The candidate''s actual stage today."}, {"term": "Last action", "definition": "What was last done and when."}, {"term": "Pending action", "definition": "What must happen next — follow-up, feedback, offer, joining confirmation."}, {"term": "Owner", "definition": "Who is responsible for the pending action."}, {"term": "Due date", "definition": "When the pending action must be completed."}, {"term": "Next follow-up", "definition": "Date and time of the next contact."}]}, {"type": "p", "text": "Common pending actions: interview pending, feedback pending, offer pending, joining pending. Each must have an owner and a date."}, {"type": "h", "text": "Fictional tracking exercise"}, {"type": "example", "title": "Situation (today is Mon 10 Mar)", "text": "Recruiter Meera J. handles: (1) Mr. Aditya P. — interviewed Fri 7 Mar, client has not shared feedback. (2) Ms. Lakshmi V. — screened Sat 8 Mar, suitable, profile not yet sent to client. (3) Mr. Rohan T. — offer accepted, joining 17 Mar, documents not yet received."}, {"type": "p", "text": "Prepare the tracking record with all seven fields for each candidate."}, {"type": "answer", "title": "Model Tracking Record", "items": [{"term": "Aditya P.", "definition": "Status: Interview Attended · Last: Interview 7 Mar · Pending: client feedback · Owner: Meera J. · Due: 10 Mar · Next follow-up: client today 12 pm; update candidate by 5 pm."}, {"term": "Lakshmi V.", "definition": "Status: Screened · Last: Screening call 8 Mar · Pending: submit profile for shortlisting · Owner: Meera J. · Due: 10 Mar · Next follow-up: inform candidate of submission today."}, {"term": "Rohan T.", "definition": "Status: Offer Accepted · Last: Acceptance received · Pending: joining documents · Owner: Meera J. · Due: 13 Mar · Next follow-up: call 11 Mar 11 am; joining reminder 16 Mar."}]}, {"type": "callout", "text": "A candidate without a next follow-up date is a candidate who will be forgotten."}]}'::jsonb from public.academy_modules where module_number = 5
