select id, 8, 'Status Updates and Pipeline Accuracy', 'Scenario: decide the correct status for real-world situations.', 'scenario', 18, true, 'active', '{"section": "B. Recruitment Pipeline", "blocks": [{"type": "h", "text": "When to change status"}, {"type": "terms", "items": [{"term": "Contacted, no response", "definition": "Status: Contacted. Record each attempt; move to No Response only after the agreed attempts."}, {"term": "Candidate confirms interest", "definition": "Move to Interested."}, {"term": "Screening call completed", "definition": "Move to Screened with the evaluation."}, {"term": "Interview date confirmed by both sides", "definition": "Move to Interview Scheduled."}, {"term": "Interviewer confirms attendance", "definition": "Move to Interview Attended."}, {"term": "Authorised selection confirmation received", "definition": "Move to Selected."}, {"term": "Offer letter released", "definition": "Move to Offered."}, {"term": "Written acceptance received", "definition": "Move to Offer Accepted."}, {"term": "Joining confirmed by client HR on the joining day", "definition": "Move to Joined."}, {"term": "Not selected", "definition": "Move to Rejected with stage and reason."}, {"term": "Candidate withdraws after offer", "definition": "Move to Dropout with reason."}]}, {"type": "h", "text": "Rules"}, {"type": "list", "items": ["Do not move a candidate forward without evidence.", "Do not leave outdated statuses — update the same day.", "Do not mark Selected before authorised confirmation.", "Do not mark Joined before actual joining confirmation."]}, {"type": "h", "text": "Fictional situations"}, {"type": "example", "title": "Situation 1", "text": "Ms. Divya R. said on the phone ''I think the interview went well, they will select me''."}, {"type": "example", "title": "Situation 2", "text": "Mr. Sameer L. accepted the offer verbally but has not replied to the offer email."}, {"type": "example", "title": "Situation 3", "text": "Mr. Kiran B. was due to join today; the candidate messaged ''reached office'', client HR has not confirmed."}, {"type": "answer", "title": "Model Answers", "items": [{"term": "Situation 1", "definition": "Status remains Interview Attended. Feedback pending from the client — candidate opinion is not evidence."}, {"term": "Situation 2", "definition": "Status remains Offered. Pending: written acceptance; follow up today."}, {"term": "Situation 3", "definition": "Do not mark Joined yet. Confirm with client HR, then update to Joined with date and time."}]}]}'::jsonb from public.academy_modules where module_number = 5
