select id, 9, 'Candidate Follow-Up and Recruitment Pipeline Management', 'Practice: plan follow-ups across a multi-candidate pipeline.', 'practice', 20, true, 'active', '{"section": "B. Recruitment Pipeline", "blocks": [{"type": "h", "text": "Follow-up principles"}, {"type": "list", "items": ["Plan follow-ups daily and prioritise by stage and urgency.", "Contact candidates at agreed or reasonable times.", "Record every outcome and the next follow-up date.", "For no response: try call and message at different times; after agreed attempts, mark No Response.", "Escalate when a client or candidate delay risks the requirement."]}, {"type": "terms", "items": [{"term": "Interview follow-up", "definition": "Same-day check with candidate; feedback chase with client within the agreed time."}, {"term": "Offer follow-up", "definition": "Confirm the candidate received and understood the offer; track acceptance deadline."}, {"term": "Joining follow-up", "definition": "Track resignation, notice, documents and joining-day confirmation."}]}, {"type": "h", "text": "Fictional pipeline (today is Wed 12 Mar, 9:30 am)"}, {"type": "example", "title": "Candidates", "text": "1) Ms. Pooja N. — Contacted 10 Mar, two unanswered calls. 2) Mr. Vikram S. — Interview Attended 11 Mar, feedback pending. 3) Ms. Anita G. — Offered 7 Mar, acceptance deadline 13 Mar, no reply. 4) Mr. Joseph M. — Offer Accepted, joining 14 Mar. 5) Mr. Harsh D. — Screened, candidate asked to be called after 15 Mar."}, {"type": "p", "text": "For each candidate decide: who needs follow-up, why, the next action, and when."}, {"type": "answer", "title": "Model Follow-Up Plan", "items": [{"term": "Anita G.", "definition": "Urgent — offer deadline tomorrow. Call 10 am today; if no reply, message and inform the client by 4 pm."}, {"term": "Joseph M.", "definition": "High — joining in 2 days. Call today to confirm documents and reporting time; reminder 13 Mar evening."}, {"term": "Vikram S.", "definition": "High — feedback pending. Chase client by 12 pm; update candidate by 5 pm."}, {"term": "Pooja N.", "definition": "Normal — third attempt by call this afternoon plus a message; mark No Response only after the agreed attempts."}, {"term": "Harsh D.", "definition": "Follow-up later — no action today; follow-up set for 16 Mar, 11 am, as requested."}]}]}'::jsonb from public.academy_modules where module_number = 5
