select id, 10, 'Daily Recruitment Workflow', 'A professional daily routine and how to prioritise work.', 'text', 18, true, 'active', '{"section": "C. Recruitment Operations", "blocks": [{"type": "h", "text": "Daily workflow"}, {"type": "steps", "items": [{"title": "Review requirements", "text": "Check open requirements, priorities and any client changes."}, {"title": "Review pending actions", "text": "List everything due today and overdue."}, {"title": "Prioritise candidates", "text": "Order work by urgency and stage."}, {"title": "Candidate follow-ups", "text": "Complete planned calls and messages."}, {"title": "Screening / interview coordination", "text": "Run screenings; confirm interview schedules."}, {"title": "Interview feedback follow-up", "text": "Chase pending feedback."}, {"title": "Offer follow-up", "text": "Track offers awaiting acceptance."}, {"title": "Joining follow-up", "text": "Track notice, documents and joining dates."}, {"title": "Update records", "text": "Statuses and notes updated the same day."}, {"title": "Prepare daily report", "text": "Based on recorded activity only."}, {"title": "Review pending work", "text": "Check nothing due today is left open."}, {"title": "Plan next actions", "text": "Set tomorrow''s follow-ups and priorities."}]}, {"type": "h", "text": "Prioritisation"}, {"type": "terms", "items": [{"term": "Urgent", "definition": "Must happen today or a candidate/requirement is at risk — e.g. offer deadline today, joining tomorrow."}, {"term": "High priority", "definition": "Time-sensitive — e.g. feedback pending, interviews to confirm."}, {"term": "Normal", "definition": "Routine progress — e.g. new screenings, sourcing for open roles."}, {"term": "Follow-up later", "definition": "Scheduled for a future date at the candidate''s or client''s request."}]}, {"type": "callout", "text": "Records first, report second. A report prepared before updating records will be wrong."}]}'::jsonb from public.academy_modules where module_number = 5
