select id, 11, 'Requirement Tracking and Client Coordination', 'Scenario: track open requirements and coordinate professionally with clients.', 'scenario', 18, true, 'active', '{"section": "C. Recruitment Operations", "blocks": [{"type": "h", "text": "Tracking requirements"}, {"type": "terms", "items": [{"term": "Requirement status", "definition": "Open, On Hold, Closed — with the date of change."}, {"term": "Number of positions", "definition": "Total, filled and remaining."}, {"term": "Candidate progress", "definition": "Count of candidates at each stage for that requirement."}, {"term": "Pending client feedback", "definition": "Profiles or interviews awaiting the client''s response."}, {"term": "Requirement changes", "definition": "Any change to skills, CTC, location or positions — recorded with who requested it."}]}, {"type": "h", "text": "Client coordination"}, {"type": "list", "items": ["Communicate politely, clearly and in writing for important points.", "Document every client instruction with date and person.", "Confirm changes in writing before acting on them.", "Escalate unclear or conflicting requirements to your team lead."]}, {"type": "h", "text": "Fictional scenario"}, {"type": "example", "title": "Requirement", "text": "Fictional client ''Northwind Retail'' — 6 Store Associates, Kochi. 2 joined, 3 at interview stage, profiles pending feedback for 4 days."}, {"type": "example", "title": "Client call", "text": "The client''s HR says on the phone: ''We may need 2 more, and maybe Malayalam is mandatory now.''"}, {"type": "answer", "title": "Model Approach", "items": [{"term": "Do not act yet", "definition": "''Maybe'' and ''may need'' are not confirmed changes."}, {"term": "Confirm in writing", "definition": "Email the client: ''To confirm: do you need 8 positions instead of 6, and is Malayalam now mandatory? I will update the search once confirmed.''"}, {"term": "Document", "definition": "Note the call with date, time and person; status of change: awaiting confirmation."}, {"term": "Pending feedback", "definition": "Raise the 4-day pending feedback politely in the same email."}, {"term": "Escalate", "definition": "If no confirmation in the agreed time, inform the team lead."}]}]}'::jsonb from public.academy_modules where module_number = 5
