select id, 12, 'Interview, Offer and Joining Follow-Up', 'Practice: manage a candidate from interview through joining.', 'practice', 20, true, 'active', '{"section": "C. Recruitment Operations", "blocks": [{"type": "h", "text": "The follow-up chain"}, {"type": "p", "text": "Interview follow-up → feedback follow-up → selection confirmation → offer follow-up → offer acceptance → joining confirmation → joining completion"}, {"type": "terms", "items": [{"term": "Pending feedback", "definition": "Chase the client at the agreed time; keep the candidate informed."}, {"term": "Candidate questions", "definition": "Answer only with confirmed information; route offer questions to authorised HR."}, {"term": "Notice-period tracking", "definition": "Confirm resignation date and last working day."}, {"term": "Joining date confirmation", "definition": "Confirm with both candidate and client in writing."}, {"term": "Joining reminders", "definition": "Remind the day before with time, address and documents."}, {"term": "Dropout handling", "definition": "Understand the reason, inform the client immediately, update to Dropout."}, {"term": "Absconded", "definition": "Joined but stopped reporting without notice — update only after client confirmation."}]}, {"type": "h", "text": "Fictional scenario"}, {"type": "example", "title": "Situation", "text": "Ms. Reshma K. interviewed on 3 Mar for a Procurement Coordinator role at fictional client ''Bluegate Engineering''. Client confirmed selection on 6 Mar. Offer released 8 Mar. Reshma has a 30-day notice and asked whether she can join on 10 Apr instead of 7 Apr."}, {"type": "p", "text": "Write the follow-up workflow from today until joining completion."}, {"type": "answer", "title": "Model Follow-Up Workflow", "items": [{"term": "Offer follow-up", "definition": "Call within 24 hrs of release — confirm receipt and understanding; written acceptance due by the deadline."}, {"term": "Joining date question", "definition": "Do not agree yourself. Ask client HR whether 10 Apr is acceptable; inform Reshma in writing once confirmed."}, {"term": "Resignation", "definition": "Confirm resignation submitted and last working day; record dates."}, {"term": "Weekly check-ins", "definition": "Brief call each week during notice to spot dropout risk early."}, {"term": "Joining reminder", "definition": "Day before: time, address, reporting person, documents."}, {"term": "Joining completion", "definition": "Confirm with client HR on the day; then update status to Joined."}]}]}'::jsonb from public.academy_modules where module_number = 5
