select id, 13, 'Recruitment Documentation and Daily Reporting', 'Accurate daily updates based only on recorded activity.', 'text', 17, true, 'active', '{"section": "C. Recruitment Operations", "blocks": [{"type": "h", "text": "What a daily report covers"}, {"type": "list", "items": ["Candidates contacted and screened", "Pipeline movement (stage changes today)", "Interviews scheduled and attended", "Selections, offers and joins", "Pending actions and blockers", "Requirement-wise summary"]}, {"type": "h", "text": "Fictional report example"}, {"type": "example", "title": "Daily report — Recruiter Arjun M., 12 Mar", "text": "Requirement: Purchase Executive (fictional client ''Southline Components'', 3 positions). Contacted 14 · Interested 6 · Screened 5 · Shortlisted 2 · Interviews scheduled 2 (13 Mar) · Selected 0 · Offers 1 pending acceptance · Joined 0. Pending: client feedback on 2 profiles since 10 Mar."}, {"type": "h", "text": "Reporting discipline"}, {"type": "list", "items": ["Every number must match recorded activity.", "Submit by the agreed deadline every day.", "Report requirement-wise, not only in totals.", "Highlight pending actions and risks honestly."]}, {"type": "compare", "title": "Reporting a slow day", "good": "Contacted 4 · Screened 1 · Pending: 3 candidates did not answer; follow-up planned tomorrow 11 am.", "bad": "Contacted 15 · Screened 6 (rounded up to match target).", "goodLabel": "Accurate", "badLabel": "Fabricated"}, {"type": "callout", "text": "Fabricated numbers are a serious breach of professional conduct. Reports drive business decisions and must reflect what actually happened."}]}'::jsonb from public.academy_modules where module_number = 5
