select id, 14, 'Recruiter Productivity, Priorities and Pending Actions', 'Scenario: put a realistic workload in the correct priority order.', 'scenario', 18, true, 'active', '{"section": "C. Recruitment Operations", "blocks": [{"type": "h", "text": "Managing workload"}, {"type": "list", "items": ["Start the day from the pending-action list, not the inbox.", "Prioritise by requirement priority, candidate stage and deadline.", "Block time for calls; batch updates.", "Do not let follow-ups slip — a missed follow-up often means a lost candidate.", "Escalate early when work exceeds capacity or a blocker is outside your control.", "End the day with a review of pending items."]}, {"type": "h", "text": "Fictional workload (Thu 9:00 am)"}, {"type": "example", "title": "Tasks", "text": "a) Candidate joins tomorrow — documents not confirmed. b) Client asked for 3 new profiles for an urgent requirement by 2 pm. c) Two interview feedbacks pending since Monday. d) Update yesterday''s notes for 6 candidates. e) Screen 4 new applicants for a normal-priority role. f) Candidate asked to be called next week."}, {"type": "p", "text": "Decide the correct priority order and explain why."}, {"type": "answer", "title": "Model Priority Order", "items": [{"term": "1 — (a)", "definition": "Urgent: joining tomorrow is at risk without documents."}, {"term": "2 — (d)", "definition": "Quick, and accurate records are needed before sharing profiles and reports."}, {"term": "3 — (b)", "definition": "Urgent client deadline at 2 pm."}, {"term": "4 — (c)", "definition": "High: feedback overdue; chase client and update candidates."}, {"term": "5 — (e)", "definition": "Normal: routine screening after urgent items."}, {"term": "6 — (f)", "definition": "Follow-up later: schedule for next week; no action today."}, {"term": "Escalate", "definition": "If (b) cannot be met by 2 pm, inform the team lead by 12 pm."}]}]}'::jsonb from public.academy_modules where module_number = 5
