select id, 15, 'Complete Recruitment Operations Workflow', 'Practice: an end-to-end fictional recruitment operations scenario.', 'practice', 23, true, 'active', '{"section": "C. Recruitment Operations", "blocks": [{"type": "h", "text": "Fictional requirement"}, {"type": "example", "title": "Requirement", "text": "Fictional client ''Harbourline Foods'' — 3 Purchase Executives, Chennai (Guindy), WFO. 2–5 yrs purchase experience in FMCG/manufacturing, SAP MM preferred, notice ≤ 30 days, CTC up to 5 LPA. Today is Fri 14 Mar. Your name: Recruiter Kavin R."}, {"type": "h", "text": "Fictional candidates"}, {"type": "example", "title": "1. Ms. Shalini P. (C-11201)", "text": "Source: Job Portal. Owner: Kavin R. Interviewed 12 Mar; client confirmed selection by email 13 Mar. Offer not yet released."}, {"type": "example", "title": "2. Mr. Arun V. (C-11214)", "text": "Source: Employee Referral (referrer: Deepa S.). Owner: Kavin R. Screened 13 Mar — suitable; profile not yet submitted."}, {"type": "example", "title": "3. Mr. Faizal M. (C-11188)", "text": "Source: Consultant. Owner: Kavin R. Offer accepted in writing 5 Mar; joining 17 Mar; relieving letter pending."}, {"type": "example", "title": "4. Ms. Rekha T. (C-11230)", "text": "Source: Walk-in. Owner: Kavin R. Contacted 13 Mar, no answer; message sent."}, {"type": "example", "title": "5. Mr. Gokul S. (C-11175)", "text": "Source: Direct Application. Owner: Kavin R. Offered 10 Mar; called 13 Mar to say he accepted a counter-offer."}, {"type": "h", "text": "For each candidate identify"}, {"type": "list", "items": ["1. Current candidate status", "2. Pending action", "3. Candidate owner", "4. Next follow-up", "5. Correct pipeline stage", "6. Required documentation", "7. Daily report information", "8. Priority action"]}, {"type": "answer", "title": "Model Recruitment Operations Plan", "items": [{"term": "Shalini P.", "definition": "Stage: Selected (authorised email). Pending: offer release — coordinate with client HR today. Owner: Kavin R. Follow-up: client HR 11 am; candidate update by 4 pm. Docs: selection email saved to record. Priority: High."}, {"term": "Arun V.", "definition": "Stage: Screened. Pending: submit for shortlisting with evaluation notes. Owner: Kavin R. Follow-up: inform candidate of submission today; chase client feedback 17 Mar. Docs: screening notes, current resume, referrer recorded. Priority: High."}, {"term": "Faizal M.", "definition": "Stage: Offer Accepted. Pending: relieving letter before 17 Mar joining. Owner: Kavin R. Follow-up: call today 10 am; joining reminder 16 Mar evening. Docs: acceptance, joining date confirmation. Priority: Urgent."}, {"term": "Rekha T.", "definition": "Stage: Contacted. Pending: second attempt. Owner: Kavin R. Follow-up: call today 3 pm; mark No Response only after agreed attempts. Docs: dated attempt notes. Priority: Normal."}, {"term": "Gokul S.", "definition": "Stage: Dropout (withdrew after offer). Pending: inform client today; record reason. Owner: Kavin R. Follow-up: none with candidate; replacement sourcing for the position. Docs: dated note with stated reason. Priority: High."}, {"term": "Priority order", "definition": "Faizal → Gokul (inform client) → Shalini → Arun → Rekha."}]}, {"type": "answer", "title": "Model Daily Report", "items": [{"term": "Requirement", "definition": "Purchase Executive — Harbourline Foods — 3 positions; 0 joined; 1 joining 17 Mar."}, {"term": "Today''s movement", "definition": "Contacted 1 · Screened 0 · Submitted 1 · Selected 0 (1 selection received 13 Mar) · Offers released 0 · Dropouts 1."}, {"term": "Pipeline", "definition": "Contacted 1 · Screened 1 · Selected 1 · Offer Accepted 1 · Dropout 1."}, {"term": "Pending actions", "definition": "Offer release for Shalini; relieving letter for Faizal; client feedback for Arun."}, {"term": "Risks", "definition": "One position reopened due to dropout; replacement sourcing started."}, {"term": "Note", "definition": "All counts taken from recorded activity on 14 Mar."}]}, {"type": "callout", "text": "Every number in the report traces back to a dated record. If it is not recorded, it did not happen."}]}'::jsonb from public.academy_modules where module_number = 5
